from urllib.parse import parse_qsl

def parse_query(qs):
    if not qs:
        return {}
    result = {}
    for key, value in parse_qsl(qs, keep_blank_values=True):
        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value
    return result
