def word_wrap(text, width):
    if not text or not text.strip():
        return []
    lines = []
    current = []
    current_len = 0
    for word in text.split():
        add = len(word) if not current else len(word) + 1
        if current_len + add <= width:
            current.append(word)
            current_len += add
        else:
            if current:
                lines.append(" ".join(current))
            current = [word]
            current_len = len(word)
    if current:
        lines.append(" ".join(current))
    return lines
```

